mapper.select:
SELECT s.*, (SELECT COUNT(*) FROM condition_equip_check_item i WHERE i.sheet_id = s.sheet_id AND i.use_yn = 'Y') AS item_count, (SELECT COUNT(*) FROM condition_equip_check_result r JOIN condition_equip_check_item i ON i.item_id = r.item_id WHERE i.sheet_id = s.sheet_id AND i.use_yn = 'Y' AND r.ym = #{ym} AND r.day = #{day}) AS today_done, (SELECT MAX(r.checked_dt) FROM condition_equip_check_result r JOIN condition_equip_check_item i ON i.item_id = r.item_id WHERE i.sheet_id = s.sheet_id) AS last_checked_dt FROM condition_equip_check_sheet s
AND s.use_yn = #{useYn}
ORDER BY s.sort_order, s.equip_name, s.sheet_id

mapper.update:
UPDATE condition_equip_check_sheet
   SET title = #{title}, equip_name = #{equipName}, model_no = #{modelNo},
       legend_json = #{legendJson}, cycle_json = #{cycleJson}, sign_json = #{signJson},
       footer_note = #{footerNote}, use_yn = #{useYn},
       upd_user_id = #{updUserId}, upd_user_name = #{updUserName}
 WHERE sheet_id = #{sheetId}

UPDATE condition_equip_check_item
   SET location = #{location}, item_name = #{itemName}, cycle = #{cycle}, range_min = #{rangeMin}, range_max = #{rangeMax}
 WHERE item_id = #{itemId}

UPDATE condition_equip_check_item
   SET photo_path = #{photoPath}, photo_name = #{photoName}, photo_type = #{photoType}
 WHERE item_id = #{itemId}

UPDATE condition_equip_check_month
   SET inspector_name = #{inspectorName}
 WHERE sheet_id = #{sheetId} AND ym = #{ym} AND (inspector_name IS NULL OR inspector_name = '')

UPDATE condition_equip_check_month
   SET inspector_name = #{inspectorName}, remark = #{remark}
 WHERE sheet_id = #{sheetId} AND ym = #{ym}

UPDATE condition_equip_check_month
   SET sign${slot}_user_id = #{userId}, sign${slot}_name = #{userName}, sign${slot}_dt = #{signDt},
       sign${slot}_img = #{signImg}
 WHERE sheet_id = #{sheetId} AND ym = #{ym}
